// lib
namespace Lib;
public class MyObject
{
    public int Id { get; set; }
    public string Name { get; set; }
}
// app
using MessagePack; using MessagePack.Formatters; using Lib;
namespace App;
// The class declares no Serialize/Deserialize. It only compiles if the generator emits the
// other half as "partial class MyObjectFormatter" (ObjectSerializationInfo.IsUserDeclaredFormatter == true)
// instead of its usual "internal sealed class" formatter.
// old: CS0246 (GeneratedMessagePackFormatterAttribute not found) + CS0535 (Serialize/Deserialize not implemented)
// new: 0 errors; generated partial supplies IMessagePackFormatter<MyObject> members
[GeneratedMessagePackFormatter]
public partial class MyObjectFormatter : IMessagePackFormatter<MyObject>
{
}
public static class Use
{
    public static byte[] Write(MyObject value)
    {
        var writer = new System.Buffers.ArrayBufferWriter<byte>();
        var w = new MessagePackWriter(writer);
        new MyObjectFormatter().Serialize(ref w, value, MessagePackSerializerOptions.Standard);
        w.Flush();
        return writer.WrittenSpan.ToArray();
    }
}
